/**
 * Bridge: turn a SuperScript (or any registered-language) script into a native
 * KLineChart indicator, so a script written by a user — or generated by AI — is
 * rendered on the SUPer-Chart canvas exactly like a built-in indicator.
 *
 * Usage:
 *   registerScriptIndicator({ name: 'SMA_CROSS', source });
 *   chart.createIndicator('SMA_CROSS', false, { id: 'candle_pane' });
 *   // later, in place (same pane, same height):
 *   updateScriptIndicator(chart, { name: 'SMA_CROSS', source: newSource });
 *
 * The template (complete line styles, histogram base and colours, finite
 * values only, legend titles, precision, inputs as calcParams) is built in
 * ./script-indicator.ts; this module binds it to klinecharts' registry.
 *
 * Maintained by ZzyzxLabs. Part of SUPer-Chart (Apache-2.0).
 */
import { registerIndicator, getSupportedIndicators } from "klinecharts";
import type { Chart } from "klinecharts";
import type { ScriptInput, ScriptParams } from "./index";
import { createScriptIndicatorBridge, sharedBridgeState, type ScriptIndicatorOptions } from "./script-indicator";

export { buildScriptIndicatorTemplate, ScriptIndicatorError, SCRIPT_PLOT_PALETTE } from "./script-indicator";
export type { ScriptIndicatorOptions, ScriptIndicatorTemplate, ScriptIndicatorErrorCode } from "./script-indicator";

// Shared with every other copy of this module on the same klinecharts (the
// CommonJS build next to the ESM one): ownership lives with the registry.
const bridge = createScriptIndicatorBridge({ registerIndicator, getSupportedIndicators }, sharedBridgeState(registerIndicator));

/**
 * Compile a script and register it as a KLineChart indicator. Returns the name.
 *
 * Throws ScriptIndicatorError NAME_TAKEN for a name that exists and was not
 * registered through this function (klinecharts' built-ins such as "RSI",
 * Super Chart's own, the host's). Registering a name this function already
 * registered replaces it for indicators created afterwards; to change the
 * ones already on a chart, use updateScriptIndicator.
 */
export function registerScriptIndicator(options: ScriptIndicatorOptions): string {
  return bridge.register(options);
}

/**
 * Replace a script indicator's script in place: re-registers it and updates
 * every instance of it on `chart` (or only on `paneId`), keeping the pane,
 * its height and its order. The new script is compiled first, so an invalid
 * one throws and leaves the chart unchanged. Inputs keep their values when
 * the script's inputs are the same; otherwise they take the new defaults.
 * With a null chart it only re-registers.
 */
export function updateScriptIndicator(chart: Chart | null, options: ScriptIndicatorOptions, paneId?: string): string {
  return bridge.update(chart, options, paneId);
}

/** The inputs of a script indicator registered through this bridge, in calcParams order. */
export function getScriptInputSchema(name: string): ScriptInput[] | undefined {
  return bridge.schema(name);
}

/**
 * Set a script indicator's inputs on `chart` by input id (`{ len: 20 }`) or
 * position, clamped to each input's minval/maxval (whole numbers for int
 * inputs). Inputs not given keep their current value. Returns the new
 * calcParams, or null when `name` is not a script indicator.
 */
export function setScriptIndicatorParams(chart: Chart, name: string, params: ScriptParams, paneId?: string): number[] | null {
  return bridge.setParams(chart, name, params, paneId);
}
